import './DataTable.css';

export type Row = {
  id: string;
  cells: string[];
};

type DataTableProps = {
  rows: Row[];
  loading: boolean;
};

const PLACEHOLDER_ROW_COUNT = 5;

export function DataTable({ rows, loading }: DataTableProps): JSX.Element {
  const placeholderRows = Array.from({ length: PLACEHOLDER_ROW_COUNT }, (_, i) => i);

  return (
    <table className="data-table">
      <tbody>
        {loading
          ? placeholderRows.map((i) => (
              <tr key={i} className="data-table-row data-table-row--shimmer">
                <td className="data-table-cell">
                  <span className="data-table-shimmer" />
                </td>
                <td className="data-table-cell">
                  <span className="data-table-shimmer" />
                </td>
                <td className="data-table-cell">
                  <span className="data-table-shimmer" />
                </td>
              </tr>
            ))
          : rows.map((row) => (
              <tr key={row.id} className="data-table-row">
                {row.cells.map((cell, j) => (
                  <td key={j} className="data-table-cell">
                    {cell}
                  </td>
                ))}
              </tr>
            ))}
      </tbody>
    </table>
  );
}
